import json
from pathlib import Path

def field(name,type,required,description):return dict(name=name,type=type,required=required,description=description)
F=field
transaction_fields=[F('external_reference','string',True,'Stable source reference, up to 120 characters. Duplicate lookup is scoped to the API key’s merchant.'),F('amount','number',False,'PHP units, >= 0. Required when gross_amount is absent.'),F('gross_amount','number',False,'PHP units, >= 0. Required when amount is absent; takes precedence if both are sent.'),F('tax_type','string',True,'vatable | vat_exempt | zero_rated | non_vat.'),F('vat_rate','number',False,'0–100; defaults to 12 in the current calculation. Tax applicability must be independently approved.'),F('vat_inclusive','boolean',False,'Defaults to true. For VAT-exclusive input, VAT is added to the supplied amount.'),F('source_system','string',False,'Source label, maximum 120 characters.'),F('channel','string',False,'Maximum 80 characters; defaults to api.'),F('transaction_type','string',False,'Maximum 80 characters; defaults to sale.'),F('payment_method','string',False,'Maximum 80 characters; defaults to cash. Payment metadata is separate from BIR acceptance.'),F('document_type','string',False,'vat_invoice | non_vat_invoice | vat_exempt_invoice | zero_rated_invoice | mixed_sales_invoice | payment_receipt | sales_invoice | official_receipt. These are NUERS identifiers, not a legal classification ruling.'),F('customer_name','string',False,'Up to 255 characters; omit in synthetic examples. Real data requires authorized handling.'),F('customer_tin','string',False,'Optional, up to 80 characters. Current request rule is string validation, not official BIR verification.'),F('branch','string',False,'Branch label, up to 255 characters.'),F('branch_name','string',False,'Branch name, up to 255 characters.'),F('branch_code','string',False,'Up to 80 characters. Confirm key-bound branch policy with the administrator.'),F('branch_type','string',False,'main | branch.'),F('receipt_number','string',False,'Optional source document number, up to 120 characters; do not bypass approved numbering controls.'),F('items','array',False,'Accepted as an array. Current ingestion does not validate per-line schema or reconcile line totals; confirm supported item structure before production.')]
sample={'external_reference':'TEST-POS-000001','source_system':'demo_pos','channel':'pos','amount':1120,'tax_type':'vatable','vat_rate':12,'vat_inclusive':True,'document_type':'sales_invoice','payment_method':'cash','branch_code':'MAIN','items':[{'description':'Synthetic example item','quantity':1,'unit_price':1120}]}
endpoints=[]
def ep(id,method,path,title,group,auth,description,fields=[],query=[],sample=None,response=None,notes=[],errors=[]):
 endpoints.append(dict(id=id,method=method,path=path,title=title,group=group,auth=auth,description=description,fields=fields,query=query,sample=sample,response=response,notes=notes,errors=errors))
ep('health','GET','/api/health','API health','Public utilities','Public','Basic application response. This is not database, queue or BIR gateway health.',response={'ok':True,'app':'NUERS Laravel API'})
ep('ingest','POST','/api/integrations/transactions','Ingest a business transaction','Merchant integration','Merchant API key','Tenant-bound transaction ingestion with transactions:write scope, active-key and exact-IP policy checks, daily quota and taxpayer issuance gate.',transaction_fields,sample=sample,response={'transaction_id':'EXAMPLE-UUID','receipt_id':'EXAMPLE-UUID','receipt_number':'EXAMPLE-DOCUMENT-NUMBER','merchant_id':'EXAMPLE-MERCHANT-UUID','branch':{'code':'MAIN','name':'Main Office'},'document':{'document_type':'sales_invoice','label':'Sales Invoice'},'tax_classification':{'gross_amount':1120,'vat_amount':120,'vatable_sales':1000}},notes=['Response shown is illustrative; successful issuance requires the actual current authority gates. Inspect the returned record, not this sample, for its state.','Merchant is resolved from the API key; there is no caller-selected merchant_id. X-NUERS-API-Key takes precedence over Authorization: Bearer.','A repeated merchant + external_reference returns HTTP 200 with duplicate=true and the existing transaction_id. Current replay handling does not compare a content hash; reconcile changed content and never reuse a reference for another transaction.','No Idempotency-Key header or public 1,000-item batch route is implemented for this endpoint.','The sandbox/live key label does not create an isolated financial ledger. Use the public developer sandbox for tests.','This endpoint enforces the issuance gate. It does not establish live BIR transmission or automatic authoritative acknowledgment.'],errors=[401,403,404,409,422,429,500])
ep('account','GET','/api/business-accounts/current','Current business account','Merchant workspace','User session','Retrieve the business linked to the authenticated user. Use the user session token, not a merchant integration key.',response={'data':{'id':'EXAMPLE-UUID','business_name':'Example business'}},errors=[401,404])
ep('transactions','GET','/api/merchant/transactions','List merchant transactions','Merchant workspace','User session','Tenant-scoped transaction list and recorded summaries.',query=[F('page','integer',False,'Default 1.'),F('per_page','integer',False,'5–100; default 15.'),F('search','string',False,'Search the supported transaction fields.'),F('status','string',False,'Filter by stored transaction status.'),F('channel','string',False,'Filter by source channel.'),F('branch','string',False,'Filter by branch label.'),F('payment','string',False,'Filter by payment method.')],response={'transactions':[],'pagination':{'page':1,'per_page':15,'total':0,'total_pages':1}},errors=[401,404])
ep('keys','GET','/api/merchant/api-keys','List merchant API keys','Credentials','User session','List masked key metadata for the authenticated merchant. Stored plaintext keys are not returned.',response={'keys':[]},errors=[401,404])
ep('create-key','POST','/api/merchant/api-keys','Create merchant API key','Credentials','User session','Create a tenant-bound machine credential. The response contains plain_key once; store it in approved secret storage.',fields=[F('name','string',True,'Maximum 255 characters.'),F('environment','string',True,'live | sandbox. Label alone is not sandbox isolation.'),F('scopes','array',False,'Explicit scope strings; transactions:write is required for transaction ingestion.'),F('ip_whitelist','array',False,'Exact source IP strings. CIDR matching is not implemented in ingestion.'),F('rate_limit_per_day','integer',False,'100–1,000,000. Defaults are 50,000 live / 5,000 sandbox.'),F('branch_type','string',False,'main | branch.'),F('branch_code','string',False,'Maximum 80 characters.'),F('branch_name','string',False,'Maximum 255 characters.'),F('branch_location','string',False,'Maximum 255 characters.')],sample={'name':'Example POS connector','environment':'sandbox','scopes':['transactions:write'],'ip_whitelist':[],'rate_limit_per_day':5000},notes=['User-session authorization and an existing merchant association are required. This operation creates access; the public sandbox does not execute it.','Key management is available through the merchant API-key dashboard. Never paste a real key into the public sandbox.'],errors=[401,404,422])
ep('key-update','PATCH','/api/merchant/api-keys/{id}','Update merchant API key policy','Credentials','User session','Update permitted metadata and access policy for an owned key. No rotate flag is implemented.',fields=[F('name','string',False,'Updated key name.'),F('active','boolean',False,'true enables; false makes the owned key inactive.'),F('scopes','array',False,'Replacement scope strings.'),F('ip_whitelist','array',False,'Replacement exact-IP allowlist.'),F('rate_limit_per_day','integer',False,'100–1,000,000.'),F('branch_type','string',False,'main | branch.'),F('branch_code','string',False,'Maximum 80 characters.'),F('branch_name','string',False,'Maximum 255 characters.'),F('branch_location','string',False,'Maximum 255 characters.')],notes=['For replacement: create a new key, update authorized consumers, verify readiness and then revoke the old key. There is no atomic rotate endpoint.'],errors=[401,404,422])
ep('key-revoke','DELETE','/api/merchant/api-keys/{id}','Revoke a merchant API key','Credentials','User session','Deactivate an owned API key through the controlled key-management route.',notes=['This changes access. The documentation and public sandbox never execute it automatically.'],errors=[401,404])
ep('readiness','GET','/api/bir-eis/readiness','EIS readiness','Administrative EIS','Admin session','Inspect recorded accreditation/taxpayer gates, checks and queue metadata. Authorized roles: admin, super_admin, bir.',response={'readiness':{'production_blocked':True,'can_submit_to_bir':False,'production_blockers':['Verified BIR production transport is not implemented.']}},notes=['Local readiness and registered credentials do not constitute BIR approval.'],errors=[401,403])
ep('eis-validate','POST','/api/bir-eis/validate','Validate internal EIS payload','Administrative EIS','Admin session','Validate the current NUERS structural payload requirements and return its canonical hash and deadline. This is not official BIR schema conformance.',fields=[F('payload','object',True,'Object or JSON string. Current checker requires a document identifier, parseable issue/transaction date, Philippine-format seller TIN and a positive total.')],sample={'payload':{'is_test':True,'invoice_number':'TEST-INV-000001','issue_date':'2026-10-15','seller_tin':'999999999000','total_due':1120,'document_type':'sales_invoice'}},response={'status':'valid','errors':[],'warnings':['Digital signature hash is not present yet; production transmission must be signed.'],'payload_hash':'EXAMPLE-SHA256','payload_size':200,'invoice_count':1,'due_at':'2026-10-18 23:59:59'},notes=['Default timezone/display rules and the actual returned due_at govern this internal check. The example is dated and illustrative.','Validation does not create a document, transmit it or establish tax correctness.'],errors=[401,403,422])
ep('eis-queue','POST','/api/bir-eis/transmissions','Queue certification payload','Administrative EIS','Admin session','Record an eligible internal transmission intent. Certification requires payload.is_test=true; production is blocked until the separate authority and transport gates pass.',fields=[F('environment','string',False,'certification | production; default certification.'),F('payload','object',True,'Internal EIS payload. Use explicit synthetic test data only in certification.')],sample={'environment':'certification','payload':{'is_test':True,'invoice_number':'TEST-INV-000001','issue_date':'2026-10-15','seller_tin':'999999999000','total_due':1120,'document_type':'sales_invoice'}},notes=['This endpoint writes queue and audit records. The public sandbox does not call it.','Document identity includes seller, branch, document type and number within an environment. Same identity/hash returns the original; changed content is rejected with 409.','A queued or simulated certification acknowledgment is not BIR acceptance.'],errors=[401,403,409,422])
ep('eis-list','GET','/api/bir-eis/transmissions','List recorded transmissions','Administrative EIS','Admin session','Search recorded queue states and attempts.',query=[F('page','integer',False,'Positive page number.'),F('per_page','integer',False,'1–100.'),F('environment','string',False,'all | production | certification | sandbox.'),F('search','string',False,'Transaction/document/taxpayer search.'),F('status','string',False,'Stored transmission status.')],errors=[401,403,422])
ep('sandbox','POST','/api/developer/sandbox','Run an isolated contract preview','Developer tools','Public','Validate synthetic transaction fields using the same shared NUERS field rules/calculation service. No financial database writes or BIR network requests.',fields=[F('is_test','boolean',True,'Must be true.'),F('action','string',True,'validate | preview | scenario.'),F('payload','object',False,'Required for validate/preview. external_reference must start TEST-, DEMO- or SAMPLE-. No credentials or private keys.'),F('scenario','string',False,'For scenario: duplicate | conflict | unauthorized | forbidden | rate_limit | timeout | production_gate.')],sample={'is_test':True,'action':'preview','payload':sample},response={'is_test':True,'environment':'isolated_preview','persisted':False,'bir_contacted':False,'bir_status':'not_submitted','status':'valid','simulated_http_status':201,'calculation':{'gross_amount':1120,'vat_amount':120}},notes=['Actual HTTP 200 carries simulated_http_status for a scenario. It does not emit a real API 401/429 or authorize retry against a production system.','20 requests/minute per limiter identity; 64 KB maximum request size; preview amount maximum PHP 1 billion.','No Authorization or X-NUERS-API-Key header is accepted. Synthetic customer TIN, if used, must be 999999999000.'],errors=[413,422,429])
meta={'version':'2026-10-15','title':'NUERS Developer API','description':'Implemented NUERS application routes. This is not an official BIR EIS API specification. Live BIR transport remains unavailable.','sample':sample,'endpoints':endpoints}
Path('resources/data/developer-catalog.json').write_text(json.dumps(meta,indent=2)+'\n')
paths={}
for e in endpoints:
 operation={'operationId':e['id'],'summary':e['title'],'description':e['description']+'\n\n'+'\n'.join(e['notes']),'tags':[e['group']],'security':[] if e['auth']=='Public' else ([{'MerchantKeyHeader':[]},{'BearerToken':[]}] if e['auth']=='Merchant API key' else [{'BearerToken':[]}]),'responses':{'200':{'description':'Successful response; review endpoint-specific status and example.'},**{str(x):{'description':{401:'Authentication required',403:'Forbidden scope/role/IP',404:'Not found',409:'State or authority conflict',413:'Payload too large',422:'Validation failed',429:'Quota exceeded',500:'Server error'}[x]} for x in e['errors']}}}
 if e['method']=='POST' and e['id'] in ['ingest','create-key','eis-queue']:operation['responses']['201']={'description':'Created record when the required gates pass.'}
 parameters=[]
 for part in e['path'].split('/'):
  if part.startswith('{'):parameters.append({'name':part[1:-1],'in':'path','required':True,'schema':{'type':'string'}})
 for f in e['query']:parameters.append({'name':f['name'],'in':'query','required':f['required'],'description':f['description'],'schema':{'type':f['type']}})
 if parameters:operation['parameters']=parameters
 if e['fields']:
  properties={f['name']:{'type':f['type'],'description':f['description'],**({'items':{}} if f['type']=='array' else {})} for f in e['fields']}
  schema={'type':'object','properties':properties};required=[f['name'] for f in e['fields'] if f['required']]
  if required:schema['required']=required
  if e['id']=='ingest':
   schema['anyOf']=[{'required':['amount']},{'required':['gross_amount']}]
   properties['tax_type']['enum']=['vatable','vat_exempt','zero_rated','non_vat']
   properties['document_type']['enum']=['vat_invoice','non_vat_invoice','vat_exempt_invoice','zero_rated_invoice','mixed_sales_invoice','payment_receipt','sales_invoice','official_receipt']
   properties['branch_type']['enum']=['main','branch']
   for name in ['amount','gross_amount','vat_rate']:properties[name]['minimum']=0
   properties['vat_rate']['maximum']=100
   for f in e['fields']:
    name=f['name']
    if f['type']=='string' and name not in ['tax_type','document_type','branch_type']:properties[name]['maxLength']=255 if name in ['branch','branch_name','customer_name'] else 120 if name in ['external_reference','source_system','receipt_number'] else 80
  if e['id']=='sandbox':
   properties['is_test']['const']=True
   properties['action']['enum']=['validate','preview','scenario']
   schema['allOf']=[{'if':{'properties':{'action':{'enum':['validate','preview']}}},'then':{'required':['payload']}}]
  if e['id'] in ['eis-validate','eis-queue']:properties['payload']['type']=['object','string']
  operation['requestBody']={'required':True,'content':{'application/json':{'schema':schema,**({'example':e['sample']} if e['sample'] else {})}}}
 paths.setdefault(e['path'],{})[e['method'].lower()]=operation
spec={'openapi':'3.1.0','info':{'title':meta['title'],'version':meta['version'],'description':meta['description']},'servers':[{'url':'/','description':'Current NUERS deployment origin; use its actual HTTPS origin outside localhost.'}],'components':{'securitySchemes':{'BearerToken':{'type':'http','scheme':'bearer','description':'User-session token for workspace/admin routes; merchant API key may be used as Bearer only on merchant integration ingestion.'},'MerchantKeyHeader':{'type':'apiKey','in':'header','name':'X-NUERS-API-Key'}}},'paths':paths}
Path('resources/data/developer-openapi.json').write_text(json.dumps(spec,indent=2)+'\n')
print(f'Generated {len(endpoints)} documented operations')
